<?php
require_once __DIR__ . '/includes/company_helpers.php';
$taxTypes=['vat'=>'قيمة مضافة','corporate_income'=>'دخل شركات','withholding'=>'خصم وتحصيل','payroll'=>'ضرائب مرتبات','other'=>'أخرى'];
if(is_post()){
 require_csrf();$id=(int)input('id');$type=company_enum(input('tax_type'),array_keys($taxTypes),'other');$period=company_input('tax_period',40);
 $start=company_valid_date(company_input('period_start',10));$end=company_valid_date(company_input('period_end',10));$dueAmount=company_decimal('amount_due');$paid=company_decimal('amount_paid');$dueDate=company_valid_date(company_input('due_date',10));$reference=company_input('reference_no',120);$notes=company_input('notes',5000);
 if($period===''||$start===false||$end===false||($start&&$end&&$end<$start)||$dueAmount===false||$paid===false||$paid>$dueAmount||$dueDate===false){company_flash_error('راجع نوع الضريبة والفترة والمبالغ والتواريخ. المسدد لا يمكن أن يتجاوز المستحق.');}
 else{$args=[$type,$period,$start,$end,$dueAmount,$paid,$dueDate,$reference?:null,$notes?:null];if($id>0){db_query('UPDATE company_tax_records SET tax_type=?,tax_period=?,period_start=?,period_end=?,amount_due=?,amount_paid=?,due_date=?,reference_no=?,notes=? WHERE id=?',array_merge($args,[$id]));company_activity('تعديل سجل ضريبي',$period);flash('success','تم تحديث السجل الضريبي.');}else{db_query('INSERT INTO company_tax_records (tax_type,tax_period,period_start,period_end,amount_due,amount_paid,due_date,reference_no,notes) VALUES (?,?,?,?,?,?,?,?,?)',$args);company_activity('إضافة سجل ضريبي',$period);flash('success','تم تسجيل المستحق الضريبي.');}redirect('taxes.php');}
}
$editId=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT)?:0;$taxRecord=$editId?db_fetch('SELECT * FROM company_tax_records WHERE id=?',[$editId]):null;
$taxes=db_fetch_all('SELECT * FROM company_tax_records ORDER BY due_date IS NULL,due_date DESC,id DESC LIMIT 300');
$sums=db_fetch('SELECT COALESCE(SUM(amount_due),0) due,COALESCE(SUM(amount_paid),0) paid FROM company_tax_records');
$adminTitle='الضرائب';$adminSubtitle='المستحقات الضريبية والمدفوعات';$adminActive='taxes';require __DIR__.'/includes/header.php';
