<div class="stats-grid"><div class="stat-card k-yellow"><div><b><?php echo e(company_money($sums['due'])); ?></b><span>إجمالي المستحق</span></div></div><div class="stat-card k-green"><div><b><?php echo e(company_money($sums['paid'])); ?></b><span>إجمالي المسدد</span></div></div><div class="stat-card k-red"><div><b><?php echo e(company_money($sums['due']-$sums['paid'])); ?></b><span>المتبقي للسداد</span></div></div></div>
